```python
from itertools import permutations

def solve_logic_puzzle():
    people = ['Blake', 'Casey', 'Parker', 'Quinn', 'Taylor']
    colors = ['blue', 'green', 'orange', 'red', 'white']
    pets = ['bird', 'cat', 'fish', 'horse', 'rabbit']
    drinks = ['coffee', 'juice', 'milk', 'tea', 'water']
    hobbies = ['baking', 'fencing', 'hiking', 'painting', 'rowing']

    def check_constraints(assignment):
        # assignment[i] = (person, color, pet, drink, hobby) for house i+1

        # Build lookup by person
        person_data = {}
        for i, (person, color, pet, drink, hobby) in enumerate(assignment):
            person_data[person] = (i, color, pet, drink, hobby)

        # Clue 1 & 6: Quinn in green house, immediately left of Casey
        quinn_idx, quinn_color = person_data['Quinn'][0], person_data['Quinn'][1]
        casey_idx = person_data['Casey'][0]

        if quinn_color != 'green':
            return False
        if quinn_idx + 1 != casey_idx:
            return False

        # Clue 5: Casey immediately left of juice drinker
        juice_idx = None
        for i, (_, _, _, drink, _) in enumerate(assignment):
            if drink == 'juice':
                juice_idx = i
                break
        if juice_idx != casey_idx + 1:
            return False

        # Clue 3: Parker does hiking
        if person_data['Parker'][4] != 'hiking':
            return False

        # Clue 4: Taylor does baking
        if person_data['Taylor'][4] != 'baking':
            return False

        # Clue 8: Parker owns rabbit
        if person_data['Parker'][2] != 'rabbit':
            return False

        # Clue 16: Quinn owns bird
        if person_data['Quinn'][2] != 'bird':
            return False

        # Clue 10: Coffee drinker does painting
        for i, (_, _, _, drink, hobby) in enumerate(assignment):
            if drink == 'coffee' and hobby != 'painting':
                return False
            if hobby == 'painting' and drink != 'coffee':
                return False

        # Clue 13: Orange house person does painting
        for i, (_, color, _, _, hobby) in enumerate(assignment):
            if color == 'orange' and hobby != 'painting':
                return False
            if hobby == 'painting' and color != 'orange':
                return False

        # Clue 11: Blue house person does rowing
        for i, (_, color, _, _, hobby) in enumerate(assignment):
            if color == 'blue' and hobby != 'rowing':
                return False
            if hobby == 'rowing' and color != 'blue':
                return False

        # Clue 2: Milk drinker next to red house
        milk_idx = red_idx = None
        for i, (_, color, _, drink, _) in enumerate(assignment):
            if drink == 'milk':
                milk_idx = i
            if color == 'red':
                red_idx = i

        if milk_idx is None or red_idx is None:
            return False
        if abs(milk_idx - red_idx) != 1:
            return False

        # Clue 12: Taylor next to red house
        taylor_idx = person_data['Taylor'][0]
        if red_idx is None or abs(taylor_idx - red_idx) != 1:
            return False

        # Clue 7: Water drinker next to Blake
        blake_idx = person_data['Blake'][0]
        water_idx = None
        for i, (_, _, _, drink, _) in enumerate(assignment):
            if drink == 'water':
                water_idx = i
                break

        if water_idx is None or abs(water_idx - blake_idx) != 1:
            return False

        # Clue 14: Juice drinker is not Taylor
        if assignment[juice_idx][0] == 'Taylor':
            return False

        # Clue 15: Horse owner next to Casey
        horse_idx = None
        for i, (_, _, pet, _, _) in enumerate(assignment):
            if pet == 'horse':
                horse_idx = i
                break

        if horse_idx is None or abs(horse_idx - casey_idx) != 1:
            return False

        # Clue 9: Fish owner doesn't drink coffee
        for i, (_, _, pet, drink, _) in enumerate(assignment):
            if pet == 'fish' and drink == 'coffee':
                return False

        return True

    # Try all permutations
    for people_perm in permutations(people):
        for color_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for drink_perm in permutations(drinks):
                    for hobby_perm in permutations(hobbies):
                        assignment = list(zip(people_perm, color_perm, pet_perm, drink_perm, hobby_perm))

                        if check_constraints(assignment):
                            # Print solution
                            print("Solution found:")
                            for i, (person, color, pet, drink, hobby) in enumerate(assignment):
                                print(f"House {i+1}: {person:8} {color:8} {pet:8} {drink:8} {hobby:8}")

                            # Find cat owner
                            for person, color, pet, drink, hobby in assignment:
                                if pet == 'cat':
                                    print(f"\nCat owner: {person}")
                                    return person

    return None

answer = solve_logic_puzzle()
```

Running through the logical deduction:

1. From clues 1, 5, 6: Quinn (green) → Casey → juice drinker (positions must be consecutive)
2. From clues 3, 4, 8, 16: Parker hikes/owns rabbit, Taylor bakes, Quinn owns bird
3. From clues 10, 13: The painter drinks coffee and lives in orange house
4. From clue 11: The rower lives in blue house
5. From clue 14: The juice drinker is not Taylor (must be Blake or Parker)

Working through the spatial constraints:
- Quinn in position 1, Casey in position 2, Blake (juice) in position 3
- From clue 12: Taylor must be next to red house
- From clue 2: Milk drinker next to red house
- This places Parker in red (position 4), Taylor in position 5 with milk

Continuing:
- From clue 7: Water drinker next to Blake (position 3) → Parker drinks water
- Coffee must go to Casey (who then is in orange house, doing painting)
- Quinn drinks tea, lives in green house
- Blake is in blue house doing rowing
- Blake owns horse (next to Casey per clue 15)
- Taylor owns fish, Casey owns cat

ANSWER: Casey
